<?php require_once __DIR__.'/includes/functions.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=trim($_POST['email']??'');$s=$conn->prepare("SELECT id,is_verified FROM users WHERE email=?");$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&!$u['is_verified']){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$exp=date('Y-m-d H:i:s',time()+86400);$v=$conn->prepare("INSERT INTO email_verifications(user_id,token_hash,expires_at) VALUES(?,?,?)");$v->bind_param('iss',$u['id'],$hash,$exp);$v->execute();$link=BASE_URL.'/verify.php?token='.$token;$sent=send_smtp_mail($email,'CCST email verification','<p><a href="'.$link.'">Verify your account</a></p>');$msg=$sent?'Verification email sent.':'Email could not be sent. Check SMTP configuration.';}else $msg='If the account exists and is unverified, a link will be sent.';}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"><link href="assets/auth.css" rel="stylesheet"><title>Resend Verification | CCST</title></head><body class="login-page"><main class="login-shell"><section class="login-brand" aria-label="Clark College of Science and Technology"><div class="brand-topline">CLARK COLLEGE OF SCIENCE AND TECHNOLOGY</div><div class="brand-seal"><img src="assets/725698283_122272196210063653_4714758265439461367_n.jpg" alt="Clark College of Science and Technology seal"></div><div class="brand-copy"><p class="brand-kicker">WELCOME TO</p><h1>CCST</h1><p class="brand-description">Student Management System</p></div><div class="brand-footer"><span>GENOSIS EXOUSIA</span><span>EST. 2005</span></div></section><section class="login-content"><div class="login-form-wrap"><div class="login-heading"><p class="login-kicker">ACCOUNT SUPPORT</p><h2>Resend verification</h2><p class="muted">Enter your email to receive a new verification link.</p></div><?php if($msg)echo '<div class="alert alert-info auth-message">'.e($msg).'</div>';?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label" for="email">Email address</label><input class="form-control login-input" id="email" name="email" type="email" placeholder="you@example.com" autocomplete="email" required><button class="btn btn-primary login-submit" type="submit">Resend email <span aria-hidden="true">&#8594;</span></button></form><div class="login-links"><a href="login.php">Back to sign in</a></div></div><div class="login-content-footer">Clark College of Science and Technology</div></section></main></body></html>
